package android.view;public class View{public int id;public ViewParent parent;public boolean enabled=true;public Runnable listener;public int clicks;private ViewGroup.LayoutParams params=new ViewGroup.LayoutParams();public ViewParent getParent(){return parent;}public ViewGroup.LayoutParams getLayoutParams(){return params;}public void setLayoutParams(ViewGroup.LayoutParams p){params=p;}public android.content.res.Resources getResources(){return new android.content.res.Resources();}@SuppressWarnings("unchecked") public <T extends View>T findViewById(int i){return id==i?(T)this:null;}public void click(){clicks++;if(enabled&&listener!=null)listener.run();}}
